      "pagina_local": "unesco-aponta-alta-nos-assassinatos-de-jornalistas-e-alerta-para-crise.html",
      "link_oficial": "https://agenciabrasil.ebc.com.br/direitos-humanos/noticia/2026-10/Unesco-189-jornalistas-foram-mortos-no-mundo-em-2024-e-2025",
